-- Simpan refleksi Ruang Ide dan pengantar halaman Naskah & kerja sama.
alter table public.site_settings
  add column if not exists editorial_content jsonb not null
  default '{"editorialIdeas":[],"submissionIntro":""}'::jsonb;


-- Adopsi tagline dan teks beranda sumber dari dokumen pemilik, hanya bila
-- record situs masih menggunakan nilai starter sebelumnya.
update public.site_settings
set tagline = 'Membuka Wacana, Menyalakan Gagasan'
where id = 'main'
  and tagline = 'Membuka wacana, menyalakan gagasan.';

update public.site_settings
set hero_lead = 'PUSTAKA ALTERNATIF menghadirkan karya yang mengajak kita membaca dengan saksama, mempertanyakan anggapan yang mapan, dan memahami kehidupan dari berbagai sudut pandang. Sebagai sebuah ikhtiar keilmuan yang serius, penerbit kami dimaksudkan untuk memperkaya wacana publik serta turut membentuk materi pendidikan dan kebijakan publik. Kami juga berupaya menjadikan hasil kajian ilmiah sebagai sarana pendidikan masyarakat dalam arti luas.'
where id = 'main'
  and hero_lead = 'Buku yang mengajak kita membaca dengan saksama, mempertanyakan anggapan yang mapan, dan memahami kehidupan dari berbagai sudut pandang.';

update public.site_settings
set about_intro = 'PUSTAKA ALTERNATIF adalah penerbit yang berorientasi pada pendidikan publik. Kami menghadirkan buku untuk memperluas akses pembaca Indonesia terhadap kajian ilmiah, pemikiran kritis, dan karya yang membuka ruang percakapan. Melalui karya asli dan terjemahan, kami ingin mempertemukan pembaca dengan gagasan yang membantu memahami agama, sejarah, kebudayaan, dan kehidupan sosial secara lebih mendalam.'
where id = 'main'
  and about_intro = 'Bagi kami, membaca adalah kesempatan untuk menguji pemahaman, mengenali pengalaman yang berbeda, dan membuka percakapan.';

-- Adopsi sinopsis dari bahan pemilik hanya bila masih tersimpan sinopsis starter.
update public.books set description = 'Siapakah Nabi Muhammad yang sesungguhnya? Nabi dalam iman yang ceritanya dilebih-lebihkan dalam bentuk mukjizat dan hal supranatural lainnya, atau sosok historis yang masih menyimpan banyak misteri? Bagaimana jika kisah-kisah dan sejarah kemunculan Islam awal mengenai Nabi Muhammad selama ini dibangun dari sumber yang perlu dibaca ulang dan dipertanyakan kesahihannya? Benarkah Islam tersebar karena mukjizat al-Qur’an, atau ada kekuatan lain yang selama ini ditutupi oleh narasi mapan? Melalui karyanya yang berjudul Kitab al-Syakhshiyyah al-Muhammadiyyah aw Hall al-Lughz al-Muqaddas, Ma''ruf al-Rusafi melakukan observasi kritis dengan membongkar sirah, hadis, tafsir, dan bahkan sisi balaghah al-Qur’an yang selama ini dipercayai sebagai dogma. Terjemahan buku karya Ma''ruf al-Rusafi ini tidak menawarkan jawaban yang nyaman, ia mengajak pembaca memasuki wilayah paling kontroversial dalam pencarian Nabi Muhammad sebagai sosok agung dalam Islam.' where slug = 'mencari-muhammad-historis' and description = 'Sebuah observasi kritis yang membongkar sirah, hadis, tafsir, dan sisi balaghah Al-Qur’an yang selama ini dipercayai sebagai dogma. Terjemahan ini tidak menawarkan jawaban yang nyaman; ia mengajak pembaca memasuki wilayah paling kontroversial dalam pencarian sosok historis Nabi Muhammad.';
update public.books set description = 'Di sebuah kampung, nama Gabalawi hidup dalam cerita dan ingatan. Rumah besarnya menyimpan kemegahan, sementara anak-cucunya bergulat dengan kemiskinan, ketakutan, dan kekuasaan para preman. Mereka mewarisi janji tentang kehidupan yang adil. Namun, siapakah yang akan menepatinya? Dari Adham hingga Gabal, Rifaa, dan Qasim, harapan terus tumbuh. Ada yang melawan dengan kekuatan. Ada yang menawarkan kasih dan pengampunan. Ada yang menyatukan mereka yang tercerai-berai. Lalu datang Arafa, membawa pengetahuan yang menjanjikan jalan baru yang sekaligus membuka pintu bagi bahaya yang tak terduga. Melalui kisah sebuah kampung, Nagib Mahfuz membentangkan pergulatan manusia dengan iman, kekuasaan, dan kerinduan akan keadilan. Tokoh-tokohnya mengingatkan kita pada kisah-kisah suci yang akrab, tetapi membawa kita ke dunia yang penuh kejutan. Di sini, para pembebas dapat dikenang sementara cita-cita mereka dilupakan. Janji keselamatan pun dapat berubah menjadi alat kekuasaan. Anak-Anak Kampung Kami mengajak kita memasuki dunia yang hangat, keras, dan meresahkan. Sebuah novel yang terus menggugah pertanyaan, bahkan setelah halaman terakhir ditutup: Jika para pembebas telah datang dan pergi, siapakah yang akan mengubah nasib kampung ini?' where slug = 'anak-anak-kampung-kami' and description = 'Melalui kisah sebuah kampung, Nagib Mahfuz membentangkan pergulatan manusia dengan iman, kekuasaan, dan kerinduan akan keadilan. Sebuah novel yang terus menggugah pertanyaan, bahkan setelah halaman terakhir ditutup.';
update public.books set description = 'Buku ini merupakan kajian akademis atas ayat-ayat polemik Al-Qur’an dan penafsirannya oleh ulama-ulama modern. Enam tafsir modern karya pembaru Muslim dari berbagai belahan dunia diuji secara kritis untuk menyingkap pandangan serta tantangan yang mereka hadapi dalam menafsirkan Kitab Suci dalam konteks dunia yang berbeda. Salah satu argumen utama buku ini ialah bahwa tafsir Al-Qur’an modern merupakan wacana penafsiran yang jauh lebih kaya dan lentur daripada yang selama ini diasumsikan. Tafsir-tafsir pembaru ditelaah dengan perhatian saksama terhadap argumen dan konteks sosio-historis untuk memperjelas metode, posisi, serta cakrawala penafsirannya. Proses ini berlangsung dalam dua arah: pembacaan kritis atas tafsir-tafsir tersebut, serta penelusuran yang jernih dan orisinal terhadap bahasa, retorika, dan dilema Al-Qur’an dalam lima topik perdebatan yang telah menyita perhatian para sarjana lintas agama. Hasilnya ialah sebuah karya dengan jangkauan konseptual yang luas dan kepekaan terhadap kompleksitas wacana keagamaan. Buku ini membuka wilayah kajian baru tentang polemik Kitab Suci, sekaligus sumbangan berharga bagi sejumlah bidang, termasuk studi Al-Qur’an, sejarah tafsir, serta perbincangan teologis yang melibatkan agama-agama Ibrahimik dan, secara lebih luas, agama-agama dunia.' where slug = 'polemik-kitab-suci' and description = 'Kajian akademis atas ayat-ayat polemik Al-Qur’an dan penafsirannya oleh ulama-ulama modern dari berbagai belahan dunia.';
update public.books set description = 'Sebelas esai yang terkumpul dalam buku ini, kendati mendiskusikan beragam tema, mempunyai benang merah yang sama, yakni hendak menggambarkan bahwa Islam merupakan agama yang membentuk dan dibentuk oleh pergulatan (engagement) yang tak pernah selesai. Yang dimaksud dengan “pergulatan” di sini ialah penafsiran yang terus berlangsung atas teks-teks fondasional dan interaksi resiprokal dengan konteks-konteks sosiohistoris yang melingkupi kemunculan dan perkembangan Islam dari zaman ke zaman. Sementara yang pertama (penafsiran atas teks) memang merupakan ciri utama dari pergulatan dengan Kitab Suci, yakni interpretasi dan reinterpretasi, yang kedua (interaksi dengan konteks sosiohistoris) juga tak terelakkan karena Islam, atau agama apapun dalam hal ini, lahir dan berkembang bukan dalam ruang hampa. Islam yang kita saksikan saat ini merupakan hasil dari pergulatan dan pergumulan yang melibatkan beragam penafsiran yang dipromosikan, dinegosiasikan, diperdebatkan, dan akhirnya terbentuk sebagai sistem keimanan yang terus berkembang dan berubah dalam kurun waktu berbeda dan lokasi berbeda.' where slug = 'interaksi-islam' and description = 'Sebelas esai yang menggambarkan Islam sebagai agama yang membentuk dan dibentuk oleh pergulatan interpretasi serta konteks sosiohistoris yang tak pernah selesai.';
update public.books set description = 'Buku ini didasarkan pada hasil penelitian lapangan yang dilakukan pada tahun 2018 dan 2019 dengan tujuan memahami, mendokumentasikan, dan menganalisis pandangan siswa SMA tentang keragaman agama, etnik, budaya dan orientasi politik, serta apa yang menyebabkan mahasiswa terpapar paham radikal. Dengan gabungan metode kuantitatif dan kualitatif, buku ini menyuguhkan data dan teori cukup gamblang, yang diharapkan membantu kita memahami fenomena intoleransi di kalangan anak muda terpelajar. Yang unik dari buku ini ialah pemaparannya yang meletakkan potret intoleransi dan radikalisme di Indonesia dalam bingkai yang lebih luas pada tataran dunia global.' where slug = 'pendidikan-dan-radikalisme' and description = 'Riset yang membantu kita memahami fenomena intoleransi di kalangan anak muda terpelajar dalam bingkai Indonesia dan dunia global.';
update public.books set description = 'Buku ini ditulis tidak untuk meragukan, apalagi mengubah keyakinan anda, para pembaca. Sebuah keyakinan itu terbentuk melalui proses yang panjang sehingga tak mungkin tergoyahkan oleh tawaran gagasan yang dikembangkan dalam buku ini. Tujuan saya sebenarnya cukup sederhana. Yakni, mengajukan sebuah perspektif tentang proses kemunculan Islam ke atas panggung sejarah. Potret historis kelahiran Islam atau Islamic origins yang disuguhkan buku ini berbeda dari keyakinan umum kaum Muslim. Karena itu, jika anda termasuk pembaca yang akan tersinggung manakala pemahaman konvensional anda dipertanyakan, maka saya anjurkan untuk tidak membaca buku ini. Saya juga tidak menganjurkan buku ini bagi mereka yang akan menelan mentah-mentah setiap informasi dan analisis at face value. Sejujurnya, saya tidak khawatir bahwa buku ini akan kehilangan pembaca, karena kedua model pembaca di atas tidaklah signifikan dari segi jumlah, jikapun ada. Tujuan buku ini ialah untuk menstimulasi munculnya pertanyaan-pertanyaan yang menggugah (bahkan, mungkin bagi sebagian orang dianggap provokatif), walaupun mungkin kita tidak bersepakat tentang jawabannya.' where slug = 'kemunculan-islam' and description = 'Perspektif tentang proses kemunculan Islam ke atas panggung sejarah dengan semangat menyambut perspektif yang beragam.';
update public.books set description = 'Buku ini seperti rekaman catatan harian yang membicarakan masalah-masalah lama dengan perspektif baru. Ia lahir dari perbincangan di dunia media sosial (medsos). Walaupun tidak seluruh tulisan dalam buku ini telah dipublikasikan di medsos, namun ide-ide dasarnya sudah pernah di-shared di Facebook. Dalam beberapa kesempatan, saya menulis status berseri tentang tema tertentu. Misalnya, soal menafsirkan al-Qur’an dengan Alkitab atau soal nikah beda agama. Tema-tema tersebut ditulis untuk memberikan wawasan kepada pembaca umum. Tidak perlu detail, namun langsung menukik ke jantung permasalahan. Diharapkan, tulisan-tulisan pendek dapat menginspirasi pembacaan lebih lanjut. Dalam buku ini gaya tutur yang populer tersebut masih tetap dipertahankan.' where slug = 'think-outside-the-box' and description = 'Catatan harian yang membicarakan masalah-masalah lama dengan perspektif baru, lahir dari perbincangan di dunia media sosial.';
update public.books set description = 'Relasi Islam dan Kristen dalam rentang sejarah yang panjang kerap digambarkan penuh ketegangan, konflik, bahkan perang berdarah. Penaklukan dan perang salib menjadi bagian dari lembaran hitam hubungan kedua komunitas agama terbesar ini. Juga, sentimen negatif yang mengemuka akibat kekhawatiran “Islamisasi” atau Kristenisasi.” Buku ini menyuguhkan gambaran koeksistensi Islam-Kristen yang berbeda. Bukan berarti ketegangan dan konflik itu tak pernah ada, melainkan bukan cerita segalanya. Ada sisi-sisi lain dari hubungan Kristen dan Muslim yang kerap diabaikan. Memang, perjumpaan kedua agama diwarnai dengan rivalitas, permusuhan dan kompetisi. Namun demikian, ada juga momen dialog terbuka, kolaborasi saling menguntungkan, dan persahabatan sejati yang tidak lusuh karena konflik. Saya berharap refleksi-refleksi santai dalam buku ini dapat menginspirasi pembaca untuk meningkatkan kesadaran akan kebersamaan. Kita perlu berikhtiar untuk berkembang bersama dalam keragaman. Kepedulian dan solidaritas kemanusiaan perlu terus ditumbuhkan. Masyarakat plural seperti Indonesia harus mensinergikan keragaman untuk perdamaian dan kemajuan bersama. Tak akan ada perdamaian di dunia tanpa koeksistensi antar-umat beragama. Tak akan ada koeksistensi antar-umat beragama tanpa persahabatan dan kerjasama antara Muslim dan Kristen. Tak akan ada kerjasama antara Muslim dan Kristen tanpa saling pengertian dan respek antar sesama umat manusia. Semoga buku ini membantu ke arah itu.' where slug = 'koeksistensi-islam-kristen' and description = 'Refleksi tentang dialog terbuka, kolaborasi yang saling menguntungkan, dan persahabatan sejati antara komunitas Muslim dan Kristen.';
update public.books set description = 'Buku ini ditulis untuk audiens pembaca yang luas: Akademisi, mahasiswa, aktivis dialog antar-agama, pemerhati studi agama-agama, dan pembaca umum. Rekonstruksi Islam Historis mendiskusikan pertanyaan-pertanyaan krusial yang sejak lama cenderung diabaikan dalam studi Islam. Bukti apa yang kita miliki untuk merekonstruksi kemunculan Islam? Kenapa sumber-sumber Muslim yang tersedia saat ini problematik untuk menyingkap peristiwa-peristiwa penting yang terjadi pada abad pertama Islam, seperti kehidupan Nabi, kodifikasi al-Qur’an atau penaklukan dan ekspansi wilayah? Bagaimana problem permulaan Islam sebagai fenomena historis itu dibingkai? Buku ini menguraikan pertanyaan di atas dan pertanyaan-pertanyaan serupa dengan merujuk pada sumber-sumber primer dan sekunder, sembari memperlihatkan perdebatan metodologis di kalangan sarjana-sarjana modern. Dengan spirit menyambut perspektif yang beragam untuk mendorong iklim perdebatan yang sehat, buku ini mengeksplorasi berbagai gagasan, metode, dan paradigma yang berseberangan. Spektrum kesarjanaan revisionis dan tradisionalis yang luas juga dihadirkan untuk mendeteksi perkembangan-perkembangan mutakhir dalam kesarjanaan modern tentang Islam, secara khusus, dan tentang kemunculan agama-agama, secara umum. Diharapkan, buku ini menghidupkan (kembali) gairah intelektual untuk mendiskusikan gagasan-gagasan penting yang menghiasi cakrawala kesarjanaan mutakhir.' where slug = 'rekonstruksi-islam-historis' and description = 'Mendiskusikan pertanyaan-pertanyaan krusial yang sejak lama cenderung diabaikan dalam studi Islam, melalui spektrum kesarjanaan revisionis dan tradisionalis.';
